export function parseQuery(input: string): Query {
  const tokens = input.trim().split(/\s+/);
  const cmd = tokens[0].toLowerCase();
  return { command: cmd, args: tokens.slice(1), raw: input.trim() };
}
export interface Query { command: string; args: string[]; raw: string; }

