import { parseQuery } from './parser';

describe('parseQuery', () => {
  it('parses simple command', () => {
    const q = parseQuery('read file.txt');
    expect(q.command).toBe('read');
    expect(q.args).toEqual(['file.txt']);
  });
  it('crashes on empty input', () => {
    expect(() => parseQuery('')).toThrow();
  });
});

